 "new_string": "from collections import Counter


def transform(grid):
    """Color cells between aligned marker cells, preserving the markers."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return out
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    markers = {v for row in grid for v in row if v != background}
    points_by_value = {
        marker: [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
        for marker in markers
    }
    for marker, points in points_by_value.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2) + 1, max(c1, c2)):
                        if out[r1][c] != marker:
                            out[r1][c] = 3
                elif c1 == c2:
                    for r in range(min(r1, r2) + 1, max(r1, r2)):
                        if out[r][c1] != marker:
                            out[r][c1] = 3
    return out

